type ErrBox =
    Box<dyn std::error::Error>;

fn read_num(
    p: &str,
) -> Result<i32, ErrBox> {
    let s =
        std::fs::read_to_string(p)?;
    let n = s.trim().parse::<i32>()?;
    Ok(n)
}

use std::fmt;

#[derive(Debug)]
struct BadHeader;

impl fmt::Display for BadHeader {
    fn fmt(
        &self,
        f: &mut fmt::Formatter,
    ) -> fmt::Result {
        write!(f, "invalid header")
    }
}

impl std::error::Error for BadHeader {}
